def flipbook_uv(frame, cols, rows, wrap):
    """帧号 -> (col, row)。wrap 取模总帧数，否则钳到末帧。"""
    total = cols * rows
    f = frame % total if wrap else min(frame, total - 1)
    return (f % cols, f // cols)


